const t=(title,body,formula)=>({title,body:'<p>'+body+'</p>',formula});
export function arrangeCourse(chapters){
 const one=chapters.find(c=>c.id==='one');
 one.theory.push(
  t('Операции над множествами','Объединение A∪B содержит элементы, принадлежащие хотя бы одному из A,B; пересечение A∩B — принадлежащие обоим. Разность A∖B содержит элементы A, не принадлежащие B. Для дополнения фиксируют универсальное множество U. Законы де Моргана проверяются по принадлежности произвольного элемента: U∖(A∪B)=(U∖A)∩(U∖B), а дополнение пересечения — объединение дополнений.','x∈A∩B ⇔ x∈A и x∈B'),
  {
   title:'Мощность множества',
   body:'<p>Мощность множества A обозначают |A|. Если A конечно, |A| равно числу его элементов. Например, |{a,b,c}|=3 для трёх различных элементов.</p>'+
    '<p>Функция f:A→B называется <strong>инъекцией</strong>, если равенство f(x₁)=f(x₂) влечёт x₁=x₂. Она называется <strong>сюръекцией</strong>, если для каждого y∈B существует x∈A с f(x)=y. <strong>Биекция</strong> — функция, обладающая обоими свойствами.</p>'+
    '<p>Для любых множеств A и B, в том числе бесконечных, равенство мощностей |A|=|B| по определению означает существование биекции A→B. Такие множества называются <strong>равномощными</strong>. Например, n↦2n задаёт биекцию между {1,2,3,…} и {2,4,6,…}, поэтому их мощности равны.</p>'+
    '<p>Пишут |A|≤|B|, если существует инъекция A→B. Пишут |A|&lt;|B|, если |A|≤|B| и |A|≠|B|.</p>',
   formula:'|A| = |B| ⇔ существует биекция A → B'
  },
  t('Множество всех подмножеств','Множество всех подмножеств A обозначают 𝒫(A). Его элементы — множества E, для которых E⊆A. В частности, ∅ и A принадлежат 𝒫(A). Для A={1,2} имеем 𝒫(A)={∅,{1},{2},{1,2}}. В этом примере |A|=2, а |𝒫(A)|=4.','𝒫(A) = {E : E ⊆ A}'),
  t('Теорема Кантора о множестве подмножеств','Для любого множества A множество 𝒫(A) имеет строго большую мощность, чем A. Для доказательства нужны два факта: существует инъекция A→𝒫(A) и не существует биекции A→𝒫(A). Второй факт следует из более сильного утверждения о том, что сюръекции A→𝒫(A) не существует.','|A| < |𝒫(A)|')
 );
 const integral=chapters.find(c=>c.id==='three');integral.title='Определённый интеграл';integral.subtitle='Интеграл Римана, суммы Дарбу, свойства, теоремы о среднем и Ньютон — Лейбниц.';integral.prerequisites='Изучите предел, непрерывность, производную и первообразную в предыдущих главах.';
 integral.theory.push(t('Верхний и нижний интегралы Дарбу','Нижний интеграл — супремум всех нижних сумм, верхний — инфимум всех верхних. Для ограниченной функции они конечны, нижний не превосходит верхнего. Интегрируемость по Риману равносильна их равенству. Для функции Дирихле, равной 1 на рациональных и 0 на иррациональных, на каждом невырожденном промежутке m=0, M=1: нижний интеграл 0, верхний b−a. Она ограниченна, но не интегрируема.','∫̲ f=sup L(f,P); ∫̅ f=inf U(f,P)'),t('Линейность, аддитивность и операции','Для интегрируемых f,g интегрируемы αf+βg, fg и |f|. Если |g|≥c>0 на отрезке, интегрируемо также f/g. Интеграл линеен и аддитивен по промежуткам: разбиение отрезка в c даёт сумму интегралов по [a,c] и [c,b]. Из f≤g следует ∫f≤∫g; строгое поточечное неравенство не всегда даёт строгое неравенство интегралов без дополнительных условий.','|∫ₐᵇ f|≤∫ₐᵇ |f|'),t('Первая теорема о среднем','Пусть f непрерывна на [a,b], g интегрируема и неотрицательна. Тогда существует ξ∈[a,b], для которого ∫fg=f(ξ)∫g. При ∫g=0 равенство выполняется для любой ξ. Доказательство использует min f·∫g≤∫fg≤max f·∫g и теорему о промежуточном значении. При g=1 получаем среднее значение интеграла.','∫ₐᵇ f(x)dx=f(ξ)(b−a) для непрерывной f'),t('Вторая теорема о среднем','Достаточная формулировка Бонне: если f монотонна на [a,b], а g непрерывна, существует ξ∈[a,b] с ∫ₐᵇfg=f(a)∫ₐ^ξg+f(b)∫ξᵇg. Здесь значения f на концах входят в формулу. Эта теорема отличается от первой: условия накладываются на монотонность множителя, а не только его знак.','∫ₐᵇ fg=f(a)∫ₐ^ξ g+f(b)∫ξᵇ g'));
 const diff=chapters.find(c=>c.id==='four');diff.title='Дифференцирование отображений';diff.prerequisites='Нужны главы о пространстве ℝⁿ, линейных отображениях, их норме, пределах и непрерывности.';
 diff.theory.push(t('Дифференциал векторного отображения','Для F:U⊆ℝⁿ→ℝᵐ, U открыто, дифференцируемость означает F(a+h)−F(a)=Lh+r(h), где L линейно и ‖r(h)‖/‖h‖→0. Дифференциал L единственен: разность двух кандидатов должна быть o(‖h‖), а на h=tv линейность вынуждает её зануляться на каждом v. Дифференцируемость равносильна дифференцируемости всех координатных функций; матрица L состоит из их частных производных.','DF(a)=JF(a),  размер m×n'),t('Высшие дифференциалы и остаток Тейлора','При F∈Cⁿ⁺¹ в окрестности отрезка a+th, 0≤t≤1, формула Тейлора получается применением одномерной теоремы к g(t)=F(a+th). Член порядка k равен DᵏF(a)[h,…,h]/k!. Интегральный остаток после порядка n равен (1/n!)∫₀¹(1−t)ⁿDⁿ⁺¹F(a+th)[h,…,h]dt. Формула верна покоординатно и для векторного F.','F(a+h)=Σₖ₌₀ⁿ DᵏF(a)[h,…,h]/k! + Rₙ'));
 const ids=SYLLABUS.flatMap(s=>s.chapters);
 const ordered=ids.map(id=>{const chapter=chapters.find(c=>c.id===id);if(!chapter)throw Error('Missing chapter '+id);const section=SYLLABUS.find(s=>s.chapters.includes(id));chapter.semester=section?.semester||0;chapter.program=section?.id||null;chapter.number=String(ids.indexOf(id)+1).padStart(2,'0');return chapter;});
 return ordered;
}
